import { createHash, randomBytes, timingSafeEqual } from 'crypto';
import { cookies } from 'next/headers';
import { getSupabaseAdmin } from './supabaseAdmin';

// Server-only: who this browser is (see components/EditMode).
//
//  - god:  the global EDIT_MODE_KEY (?mode=<key>): every editing feature, everywhere,
//          including the King features of every kingdom.
//  - king: a per-kingdom King key generated by god on the Kingdom page. Only the
//          King features of that kingdom (kingdom-wide gift codes, updating every
//          player of the kingdom, the Jail). A High King gets no key.
//
// Each role lives in its own httpOnly cookie holding a hash of its key, so a new
// EDIT_MODE_KEY / regenerated King key turns the old one off everywhere.

export const GOD_COOKIE = 'kam-edit-mode';
export const KING_COOKIE = 'kam-king';
export const COOKIE_MAX_AGE = 60 * 60 * 24 * 365; // a year

export const cookieOptions = {
  httpOnly: true,
  secure: process.env.NODE_ENV === 'production',
  sameSite: 'lax' as const,
  path: '/',
  maxAge: COOKIE_MAX_AGE,
};

const godKey = () => process.env.EDIT_MODE_KEY ?? '';
export const hashGodKey = (value: string) => createHash('sha256').update(`kam-edit-mode:${value}`).digest();
export const hashKingKey = (value: string) => createHash('sha256').update(`kam-king-key:${value}`).digest('hex');

const sameBytes = (a: Buffer, b: Buffer) => a.length === b.length && timingSafeEqual(a, b);

export function isGodKey(given: string): boolean {
  const key = godKey();
  return !!key && !!given && sameBytes(hashGodKey(given), hashGodKey(key));
}

/** A new random King key (shown once, only its hash is stored). */
export const newKingKey = () => randomBytes(24).toString('base64url');

/** The kingdom a King key belongs to, or null. */
export async function findKingdomForKingKey(given: string): Promise<number | null> {
  const db = getSupabaseAdmin();
  if (!db || !given || given.length > 200) return null;
  const { data } = await db
    .from('kingdom_king_key')
    .select('kingdomId')
    .eq('key_hash', hashKingKey(given))
    .maybeSingle();
  return data ? Number(data.kingdomId) : null;
}

export interface Access {
  god: boolean;
  /** Kingdom id this browser is the King of (null when not a King) */
  kingOf: number | null;
}

/** Roles of the current request, from its cookies (King cookie re-checked against the DB). */
export async function getAccess(): Promise<Access> {
  const store = await cookies();

  const key = godKey();
  const godCookie = store.get(GOD_COOKIE)?.value;
  const god = !!key && !!godCookie && sameBytes(Buffer.from(godCookie, 'hex'), hashGodKey(key));

  let kingOf: number | null = null;
  const kingCookie = store.get(KING_COOKIE)?.value;
  const db = getSupabaseAdmin();
  if (kingCookie && db && /^[0-9a-f]{64}$/.test(kingCookie)) {
    const { data } = await db.from('kingdom_king_key').select('kingdomId').eq('key_hash', kingCookie).maybeSingle();
    kingOf = data ? Number(data.kingdomId) : null;
  }

  return { god, kingOf };
}

/** God, or the King of this kingdom: may use the King features there. */
export const canRule = (access: Access, kingdomId: number) => access.god || access.kingOf === kingdomId;
